import React, { useEffect, useRef } from 'react';
import type { PageProps } from 'gatsby';
import { Helmet } from 'react-helmet';
import Header from '../Components/header';
import Footer from '../Components/Footer';
import { localBusinessSchema } from '../data/business';
import '../Styles/InstantQuote.css';

/**
 * Roofle "Roof Quote PRO" — Embedded widget (account MTC-BRI-21).
 *
 * Roofle ships this as a <body> script. In Gatsby/React we inject it into the
 * container below on mount so the tool renders in place on the page.
 * The Slideout version is installed globally — see gatsby-ssr.js.
 */
const ROOFLE_EMBED_SRC =
  'https://app.roofle.com/roof-quote-pro-embedded-widget.js?id=EydHLCaXd1diLHD87YGpA';

const InstantQuotePage: React.FC<PageProps> = () => {
  const widgetRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const container = widgetRef.current;
    if (!container) return;

    const script = document.createElement('script');
    script.src = ROOFLE_EMBED_SRC;
    script.async = true;
    container.appendChild(script);

    // Clean up on unmount so client-side navigation can't stack duplicates.
    return () => {
      script.remove();
      container.innerHTML = '';
    };
  }, []);

  return (
    <>
      <Helmet>
        <title>Instant Roof Quote | Bravo Roofing LLC</title>
        <meta
          name="description"
          content="Get an instant roof replacement quote online in minutes. Enter your address for accurate, real-time pricing from Bravo Roofing in Boise, Idaho."
        />
        <meta property="og:title" content="Instant Roof Quote | Bravo Roofing LLC" />
        <meta
          property="og:description"
          content="Get an instant roof replacement quote online in minutes from Bravo Roofing in Boise, Idaho."
        />
        <meta property="og:url" content="https://www.bravoroofingidaho.com/instant-quote/" />
        <script type="application/ld+json">{JSON.stringify(localBusinessSchema("/instant-quote/"))}</script>
      </Helmet>

      <Header />

      <main className="instant-quote-page">
        <section className="instant-quote-intro">
          <h1>Get Your Instant Roof Quote</h1>
          <p>
            Enter your address below to see real-time pricing for your new roof — no
            phone call required. It only takes a minute, and there's no obligation.
          </p>
        </section>

        <section className="instant-quote-widget">
          <div ref={widgetRef} className="roofle-widget-container" />
        </section>
      </main>

      <Footer />
    </>
  );
};

export default InstantQuotePage;
